package android.view;
public abstract class ViewStructure { public abstract void setId(int id,String packageName,String typeName,String entryName); public abstract void setDimens(int left,int top,int scrollX,int scrollY,int width,int height); public abstract void setClassName(String name); public abstract void setText(CharSequence text); public abstract void setContentDescription(CharSequence description); public void setAutofillId(android.view.autofill.AutofillId id){} public void setChildCount(int count){} public void setHint(CharSequence hint){} public abstract int addChildCount(int num); public abstract ViewStructure newChild(int index); }
